  void AddParallelBranch(){CapturePose();var source=Joint;if(source==null)return;var poses=RobotKinematics.Evaluate(Document,0,false);var pose=poses[source.Id];var direction=pose.Tip-pose.Origin;if(direction.Length<1e-6)direction=new Vector3D(1,0,0);direction.Normalize();var side=Vector3D.CrossProduct(new Vector3D(0,0,1),direction);if(side.Length<1e-6)side=new Vector3D(1,0,0);side.Normalize();double envelope=Document.Joints.Max(x=>Math.Max(x.GearboxDiameter,Math.Max(x.SkinDiameter,x.MotorFrame)));double shift=poses.Values.Max(x=>Math.Max(Vector3D.DotProduct((x.Origin-pose.Origin),side),Vector3D.DotProduct((x.Tip-pose.Origin),side)))+Math.Max(100,envelope+20);var origin=pose.Origin+side*shift;Mutate(()=>{var j=CADDocument.Serializer().Deserialize<RobotJoint>(CADDocument.Serializer().Serialize(source));var added=Document.Add(null);j.Id=added.Id;j.Name=added.Name+" · параллельная ветвь";j.ParentId=null;j.GeneratedBody=null;if(j.BodyGenerator!=null){j.BodyGenerator.Variant="Reference";ApplyBodyVariant(j,0);}j.Position=0;j.Minimum=Math.Min(0,j.Minimum);j.Maximum=Math.Max(0,j.Maximum);j.Mode=Math.Abs(direction.Y)>.7?RobotJointMode.Вращение_X:RobotJointMode.Вращение_Y;j.AxisReversed=false;j.EndX=direction.X*source.Length;j.EndY=direction.Y*source.Length;j.EndZ=direction.Z*source.Length;j.OffsetX=origin.X;j.OffsetY=origin.Y;j.OffsetZ=origin.Z;Document.Joints[Document.Joints.Count-1]=j;selectedJoint=j.Id;selectedPart=null;});}



