  void RefreshQuickLoad(){if(quickLoad==null||Analysis==null)return;var state=Analysis.Joints.FirstOrDefault(x=>x.Id==selectedJoint);if(state!=null)quickLoad.Text="Нужно с запасом: "+Engine.F(state.Required)+" "+state.Unit+"\nДоступно: "+Engine.F(state.Available)+" "+state.Unit+"\n"+state.Message;}

  void BeginPoseEdit(){if(poseEditing)return;Stop();EnsurePoseSaveBaseline();poseEditing=true;poseBefore=CapturePoseHistory();if(Math.Abs(phase)>1e-9){var current=RobotKinematics.Evaluate(Document,phase,true);foreach(var j in Document.Joints)j.Position=current[j.Id].Value;phase=0;}}

  internal void SetJointPose(string id,double value){var joint=Document.Find(id);if(joint==null||!MechanismCad.Finite(value))return;Stop();joint.Position=Math.Max(joint.Minimum,Math.Min(joint.Maximum,value));RefreshManualPose();}

  void EndPoseEdit(){if(!poseEditing)return;string current=CapturePoseHistory();if(poseBefore!=current){PushRobotHistory(undo,poseBefore);redo.Clear();}poseEditing=false;poseBefore=null;UpdatePoseTitle();SyncJointControllers();}

  W.Point ProjectBone(Point3D point){var d=point-Scene.Camera.Target;double scale=Scene.Root.ActualWidth/Math.Max(.01,Scene.Camera.Width);return new W.Point(Scene.Root.ActualWidth/2+Vector3D.DotProduct(d,Scene.Camera.Right)*scale,Scene.Root.ActualHeight/2-Vector3D.DotProduct(d,Scene.Camera.Up)*scale);}

  void RefreshBoneOverlay(){if(boneDragging||boneOverlay.Parent==null||Build==null||!Scene.Ready)return;boneOverlay.Children.Clear();if(stage!=0&&view.SelectedIndex!=0&&(move==null||!move.Checked))return;var poses=RobotKinematics.Evaluate(Document,phase,Math.Abs(phase)>1e-9);foreach(var j in Document.Joints){var p=poses[j.Id];var origin=ProjectBone(p.Origin);var dot=new WC.Button{Content=(Document.Joints.IndexOf(j)+1).ToString(),Width=27,Height=27,Background=j.Id==selectedJoint?WM.Brushes.DarkOrange:WM.Brushes.SteelBlue,Foreground=WM.Brushes.White,ToolTip=j.Name+" · выбрать шарнир"};WC.Canvas.SetLeft(dot,origin.X-13);WC.Canvas.SetTop(dot,origin.Y-13);string id=j.Id;dot.Click+=(s,e)=>Select(id,null);boneOverlay.Children.Add(dot);if(j.Id!=selectedJoint)continue;var tip=ProjectBone(p.Tip);var line=new Shapes.Line{X1=origin.X,Y1=origin.Y,X2=tip.X,Y2=tip.Y,Stroke=WM.Brushes.DarkOrange,StrokeThickness=2,StrokeDashArray=new WM.DoubleCollection(new[]{4.0,3}),IsHitTestVisible=false};boneOverlay.Children.Add(line);var label=new WC.TextBlock{Text=j.Name+" · "+Engine.F(j.Length)+" мм",Background=WM.Brushes.White,Foreground=WM.Brushes.DarkSlateGray,Padding=new W.Thickness(5),IsHitTestVisible=false};WC.Canvas.SetLeft(label,tip.X+16);WC.Canvas.SetTop(label,tip.Y-10);boneOverlay.Children.Add(label);if(playing||Math.Abs(phase)>1e-9)continue;var thumb=new System.Windows.Controls.Primitives.Thumb{Width=23,Height=23,Background=WM.Brushes.OrangeRed,ToolTip="Потяните конец звена. Ось перемещения задаётся над сценой."};var border=new W.FrameworkElementFactory(typeof(WC.Border));border.SetValue(WC.Border.BackgroundProperty,WM.Brushes.OrangeRed);border.SetValue(WC.Border.CornerRadiusProperty,new W.CornerRadius(12));thumb.Template=new WC.ControlTemplate(typeof(System.Windows.Controls.Primitives.Thumb)){VisualTree=border};WC.Canvas.SetLeft(thumb,tip.X-11);WC.Canvas.SetTop(thumb,tip.Y-11);thumb.DragStarted+=(s,e)=>{boneDragging=true;boneStart=System.Windows.Input.Mouse.GetPosition(Scene.Root);boneDelta=new Vector3D();};thumb.DragDelta+=(s,e)=>{boneDelta=Scene.DragDelta(boneStart,System.Windows.Input.Mouse.GetPosition(Scene.Root));WC.Canvas.SetLeft(thumb,ProjectBone(p.Tip+boneDelta).X-11);WC.Canvas.SetTop(thumb,ProjectBone(p.Tip+boneDelta).Y-11);};thumb.DragCompleted+=(s,e)=>{boneDragging=false;if(!e.Canceled&&boneDelta.LengthSquared>1e-8)CommitDrag(id+"_end_guide",boneDelta);RefreshBoneOverlay();};boneOverlay.Children.Add(thumb);}}

